#!/usr/bin/env node
/**
 * Runs the `@visual` suite inside the pinned Playwright container.
 *
 * Issue #61 asked for this as a script rather than a README paragraph, and the
 * reason is narrow and specific: a baseline generated by a bare
 * `npx playwright test --update-snapshots` on a developer's own machine is
 * rasterised by that machine's font stack, so it diffs against CI's output on
 * day one for reasons that have nothing to do with the UI. The container is the
 * only place a baseline may be produced, and a command nobody can mistype is
 * the cheapest way to keep that true.
 *
 * The image tag is DERIVED from package.json's pinned `@playwright/test`, never
 * written here — so bumping the library cannot leave this script pointing at
 * the old browser build. `scripts/check-playwright-image-tag.mjs` asserts the
 * same agreement for the workflow files.
 *
 * Usage:
 *   npm run e2e:visual                 # compare against the committed baselines
 *   npm run e2e:visual:update          # regenerate them
 *   npm run e2e:visual -- --grep chat  # extra args pass straight through
 *
 * The stack must already be up (`./scripts/e2e-stack.sh up && … seed`):
 * `E2E_REUSE_STACK=1` stops Playwright trying to start it from inside a
 * container that has no container runtime — see playwright.config.ts.
 */
import { spawnSync } from 'node:child_process';
import { readFileSync } from 'node:fs';
import path from 'node:path';
import process from 'node:process';
import { fileURLToPath } from 'node:url';

const appRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const pkg = JSON.parse(readFileSync(path.join(appRoot, 'package.json'), 'utf8'));
const pinned = pkg.devDependencies?.['@playwright/test'] ?? pkg.dependencies?.['@playwright/test'];

if (typeof pinned !== 'string' || !/^\d+\.\d+\.\d+$/.test(pinned)) {
  console.error(`run-visual-container: @playwright/test must be pinned exactly, found ${JSON.stringify(pinned)}`);
  process.exit(2);
}

const image = `mcr.microsoft.com/playwright:v${pinned}-noble`;
// podman, not docker (this repo's CLAUDE.md); overridable for CI images that
// only ship docker.
const runtime = process.env['CONTAINER_RUNTIME'] ?? 'podman';

const args = [
  'run', '--rm',
  // The stack runs on the host, so the test container must share its network.
  // A job container would NOT work: it does not share the runner's network
  // namespace, so BASE_URL=http://localhost:8082 would not reach the stack.
  '--network', 'host',
  '-v', `${appRoot}:/work`,
  '-w', '/work',
  '-e', 'CI=1',
  '-e', 'E2E_REUSE_STACK=1',
  image,
  'npx', 'playwright', 'test', '--project=visual',
  ...process.argv.slice(2),
];

console.log(`run-visual-container: ${runtime} ${args.join(' ')}`);
const result = spawnSync(runtime, args, { stdio: 'inherit' });

if (result.error) {
  console.error(`run-visual-container: could not start ${runtime}: ${result.error.message}`);
  process.exit(2);
}
process.exit(result.status ?? 1);
